"use strict";(self.webpackChunkchatgpt_shortcut=self.webpackChunkchatgpt_shortcut||[]).push([["44012"],{8595(e){e.exports=JSON.parse('{"id":9389,"title":"\u5373\u68A6\u3001\u8C46\u5305P\u56FE\u6307\u4EE4_\u957F\u6587\u672C\u63D0\u793A\u8BCD2","description":"80.\u4E00\u7EC4\u5C55\u73B0\u79CB\u65E5\u6C1B\u56F4\u611F\u7684\u4E09\u5BAB\u683C\u4EBA\u50CF\u8857\u62CD\u6444\u5F71\uFF0C\u6BCF\u9694\u4E4B\u95F4\u6709\u767D\u8272\u8FB9\u6846\uFF0C\u573A\u666F\u4E3A\u57CE\u5E02\u6709\u843D\u53F6\u7684\u8857\u9053\u4E0A\uFF0C\u80CC\u666F\u662F\u5E26\u6709\u88C5\u9970\u7684\u5899\u9762\u548C\u9A6C\u8DEF\u65C1\u7684\u6811\u6728\u3002\u7B2C\u4E00\u683C\uFF1A\u624B\u5199\u5B57\u4F53\u201C\u5728\u79CB\u5929\u7F16\u7EC7\u6BCF\u4E00\u4E2A\u5C0F\u6545\u4E8B\u201D\uFF0C\u4EBA\u7269\u7AD9\u5728\u8857\u9053\u4E0A\uFF0C\u9762\u5E26\u5FAE\u7B11\u4EF0\u5934\uFF1B\u7B2C\u4E8C\u683C\uFF1A\u4EBA\u7269\u7AD9\u5728\u8857\u9053\u4E0A\uFF0C\u4EBA\u7269\u7A81\u51FA\u767D\u8272\u8FB9\u6846\u5916\u5360\u636E\u7B2C\u4E00\u5F20\u753B\u9762\u7684\u4E00\u534A\u5185\u5BB9\uFF0C\u95ED\u7740\u773C\u775B\uFF0C\u9762\u5E26\u7B11\u610F\uFF0C\u53CC\u81C2\u8212\u5C55\uFF1B\u7B2C\u4E09\u683C\uFF1A\u82F1\u6587\u5B57\u4F53\u201CWeave every little storyin autumn\u201D\uFF0C\u4EBA\u7269\u80CC\u5BF9\u7740\u955C\u5934\uFF0C\u7AD9\u5728\u8857\u9053\u4E0A\u3002\u6574\u4F53\u573A\u666F\u5145\u6EE1\u79CB\u65E5\u6D6A\u6F2B\u3001\u6587\u827A\u7684\u6C1B\u56F4\uFF0C\u8272\u8C03\u6E29\u6696\u67D4\u548C\\n81.\u6797\u95F4\u94FA\u6EE1\u91D1\u9EC4\u843D\u53F6\uFF0C\u56FE\u4E2D\u4EBA\u7269\u7A7F\u7740\u6D45\u84DD\u4E0A\u8863\u3001\u683C\u7EB9\u88D9\u5750\u5728\u5176\u4E2D\uFF0C\u6B6A\u5934\u671B\u5411\u955C\u5934\uFF0C\u624B\u6301\u67AB\u53F6\uFF0C\u524D\u666F\u96F6\u661F\u7684\u6563\u843D\u7740\u51E0\u4E2A\u6A59\u7EA2\u7684\u67FF\u5B50\uFF0C\u4E0D\u8FDC\u5904\u6709\u4E2A\u7F16\u7EC7\u7BEE\u3002\u9633\u5149\u900F\u8FC7\u679D\u53F6\u6D12\u843D\uFF0C\u7ED9\u6574\u4E2A\u573A\u666F\u9540\u4E0A\u6696\u8C03\\n82.\u56DB\u5BAB\u683C\u4EBA\u50CF\u5199\u771F\uFF0C\u7EDF\u4E00\u4EE5\u9C9C\u660E\u7EA2\u8272\u4E3A\u80CC\u666F\uFF0C\u76F4\u89C2\u8425\u9020\u6D53\u539A\u7231\u56FD\u6C1B\u56F4\u4E0E\u56FD\u5E86\u8282\u65E5\u559C\u5E86\u611F\u3002\u753B\u9762\u4E2D\u4EBA\u7269\u8EAB\u7740\u9970\u6709\u91D1\u8272\u9F99\u7EB9\u7684\u4F20\u7EDF\u670D\u9970\uFF0C\u8138\u90E8\u70B9\u7F00\u201CChina\u201D\u5B57\u6837\u8D34\u7EB8\u3001\u7231\u5FC3\u8D34\u7EB8\u7B49\u56FD\u5E86\u4E3B\u9898\u88C5\u9970\u5143\u7D20\uFF0C\u5F3A\u5316\u8282\u65E5\u5C5E\u6027\u3002\u4EBA\u7269\u59FF\u6001\u4E0E\u795E\u6001\u4E30\u5BCC\u591A\u6837\uFF1A\u6216\u53CC\u624B\u6BD4\u51FA\u7231\u5FC3\u624B\u52BF\uFF0C\u6216\u624B\u6301\u5370\u6709\u201C\u6B22\u5EA6\u56FD\u5E86\u201D\u201C\u7231\u6211\u4E2D\u534E\u201D\u5B57\u6837\u7684\u7EA2\u8272\u6A2A\u5E45\uFF0C\u6216\u4FCF\u76AE\u561F\u5634\u3001\u6216\u6D3B\u6CFC\u7728\u773C\u3001\u6216\u5411\u955C\u5934\u5A07\u4FCF\u98DE\u543B\uFF0C\u901A\u8FC7\u7075\u52A8\u7684\u52A8\u4F5C\u4E0E\u751F\u52A8\u7684\u795E\u6001\uFF0C\u7CBE\u51C6\u4F20\u9012\u5BF9\u7956\u56FD\u7684\u771F\u631A\u70ED\u7231\u4E0E\u6B22\u5E86\u56FD\u5E86\u7684\u559C\u60A6\u5FC3\u60C5\u3002\u6574\u4F53\u753B\u9762\u98CE\u683C\u660E\u5FEB\u559C\u5E86\uFF0C\u5145\u6EE1\u9752\u6625\u6D3B\u529B\uFF0C\u5DE7\u5999\u5C06\u4F20\u7EDF\u670D\u9970\u7684\u6587\u5316\u97F5\u5473\u4E0E\u70BD\u70ED\u7684\u7231\u56FD\u60C5\u6000\u878D\u5408\uFF0C\u4F7F\u89C6\u89C9\u6548\u679C\u4E0E\u60C5\u611F\u8868\u8FBE\u9AD8\u5EA6\u7EDF\u4E00\u3002\\n83.\u4EBA\u50CF\u5199\u771F\uFF0C\u4E2D\u5FC3\u6784\u56FE\uFF0C\u53BB\u6389\u6742\u7269\uFF0C\u4EBA\u7269\u8EAB\u7740\u534E\u4E3D\u98D8\u9038\u660E\u5236\u6C49\u670D\uFF0C\u5927\u8896\u886B\u3001\u5934\u6234\u7CBE\u81F4\u5934\u9970\uFF0C\u5468\u56F4\u73AF\u7ED5\u7740\u7EA4\u7EC6\u7684\u53D1\u5149\u91D1\u9C7C\uFF0C\u4E0A\u65B9\u6709\u4E00\u76CF\u6696\u9EC4\u8272\u5B54\u660E\u706F\uFF0C\u80CC\u666F\u662F\u706F\u706B\u8F89\u714C\u7684\u53E4\u98CE\u5EFA\u7B51\uFF0C\u6574\u4F53\u6696\u8272\u8C03\uFF0C\u80CC\u666F\u865A\u5316\u3002\\n84.\u65F6\u5C1A\u6742\u5FD7\u5C01\u9762\uFF0C\u9876\u90E8\u767D\u8272\u5927\u6807\u9898\uFF1A OCTOBER\uFF0C\u4EBA\u7269\u8EAB\u7740\u7C73\u767D\u8272\u590D\u53E4\u8FDE\u8863\u88D9\uFF0C\u624B\u6301\u6A59\u767D\u82B1\u6735\u4E0E\u5E72\u82B1\u7684\u82B1\u675F\uFF0C\u5934\u53D1\u81EA\u7136\u5FAE\u5377\uFF0C\u7B80\u7EA6\u6D45\u8272\u8C03\u80CC\u666F\uFF0C\u5149\u5F71\u6591\u9A73\uFF0C\u80CC\u666F\u7A7F\u63D2\u6D45\u68D5\u8272\u6587\u5B57\uFF1A NEW SEASON\uFF0CCOOL GIRL\uFF0C\u53F3\u4E0B\u65B9\u6D45\u7070\u8272\u624B\u5199\u82B1\u4F53\u5B57\uFF1A every day is good day\uFF0C\u9AD8\u7EA7\u65F6\u5C1A\u4EBA\u50CF\uFF0C\u67D4\u548C\u5149\u5F71\uFF0C\u7EC6\u817B\u8D28\u611F\\n85.\u4EE5\u8F93\u5165\u56FE\u4E2D\u7684\u4EBA\u7269\u4E3A\u6838\u5FC3\uFF0C\u5448\u73B0\u5176\u5728\u827A\u672F\u5C55\u89C8\u73B0\u573A\u4E0E\u5DE8\u578B\u88C5\u7F6E\u5408\u5F71\u7684\u573A\u666F\u3002\u8BE5\u88C5\u7F6E\u4E3A\u5361\u901A\u4EBA\u7269\u9020\u578B\uFF0C\u9700\u4E25\u683C\u6CBF\u7528\u8F93\u5165\u56FE\u7684\u8272\u5F69\u4F53\u7CFB\uFF0C\u4FDD\u7559\u201C\u5927\u773C\u775B\u201D\u840C\u7CFB\u827A\u672F\u98CE\u683C\uFF1B\u540C\u65F6\uFF0C\u88C5\u7F6E\u5F62\u8C61\u9700\u6DF1\u5EA6\u590D\u523B\u4EBA\u7269\u7684\u670D\u9970\u7248\u578B\u3001\u914D\u9970\u7EC6\u8282\u3001\u53D1\u578B\u8BBE\u8BA1\u53CA\u88C5\u9970\u5143\u7D20\uFF0C\u786E\u4FDD\u4E0E\u4EBA\u7269\u5728\u4E3B\u4F53\u5F62\u8C61\u3001\u6027\u522B\u7279\u5F81\u3001\u9762\u90E8\u76F8\u4F3C\u5EA6\u4E0A\u9AD8\u5EA6\u7EDF\u4E00\uFF0C\u4E14\u88C5\u7F6E\u9700\u5B8C\u6574\u7A7F\u7740\u5BF9\u5E94\u670D\u88C5\u3002\u6784\u56FE\u4E0A\uFF0C\u88C5\u7F6E\u4EE5\u81EA\u7136\u7AD9\u59FF\u7F6E\u4E8E\u4EBA\u7269\u659C\u4FA7\u540E\u65B9\uFF0C\u4F53\u79EF\u663E\u8457\u5927\u4E8E\u4EBA\u7269\uFF0C\u9AD8\u5EA6\u7EA6\u4E3A\u4EBA\u7269\u76841.5\u500D\uFF0C\u4EE5\u6B64\u5F3A\u5316\u89C6\u89C9\u6BD4\u4F8B\u53CD\u5DEE\u3002\u80CC\u666F\u8BBE\u5B9A\u4E3A\u7B80\u7EA6\u89C2\u5C55\u7A7A\u95F4\uFF0C\u901A\u8FC7\u5E72\u51C0\u7684\u73AF\u5883\u4E0E\u67D4\u548C\u7684\u6C1B\u56F4\uFF0C\u8425\u9020\u5B89\u9759\u3001\u9AD8\u7EA7\u7684\u89C2\u5C55\u8D28\u611F\u3002\u753B\u9762\u6280\u672F\u5C42\u9762\uFF0C\u9700\u4FDD\u8BC1\u6574\u4F53\u5149\u5F71\u81EA\u7136\u878D\u5408\u3001\u6C1B\u56F4\u548C\u8C10\u7EDF\u4E00\uFF0C\u4EBA\u7269\u7684\u8138\u90E8\u8868\u60C5\u81EA\u7136\u3001\u8EAB\u4F53\u6BD4\u4F8B\u534F\u8C03\u3001\u624B\u90E8\u7EC6\u8282\u5B8C\u6574\uFF0C\u65E0\u4EFB\u4F55\u5D29\u574F\u6216\u9519\u4E71\u95EE\u9898\u3002\\n86.\u4E3A\u4E0A\u4F20\u7684\u4EBA\u7269\u5B9A\u5236\u4E00\u5F20\u5BCC\u6709\u6C1B\u56F4\u611F\u7684\u5DE5\u4F5C\u5BA4\u8096\u50CF\u7167\u3002\u753B\u9762\u6838\u5FC3\u4E3A\u4EBA\u7269\uFF0C\u4EE5\u91D1\u6A59\u8272\u805A\u5149\u706F\u4E3A\u4E3B\u8981\u5149\u6E90\uFF0C\u5728\u4EBA\u7269\u8EAB\u540E\u5899\u9762\u6253\u9020\u51FA\u6E05\u6670\u4E14\u95EA\u4EAE\u7684\u5706\u5F62\u5149\u6655\uFF1B\u6696\u5149\u9700\u5448\u67D4\u548C\u5915\u9633\u8272\u8C03\uFF0C\u7CBE\u51C6\u52FE\u52D2\u4EBA\u7269\u8138\u90E8\u8F6E\u5ED3\u4E0E\u4E0A\u534A\u8EAB\u7EBF\u6761\uFF0C\u540C\u65F6\u5728\u4EBA\u7269\u53F3\u4FA7\u533A\u57DF\u6295\u5C04\u51FA\u9C9C\u660E\u3001\u6709\u5C42\u6B21\u611F\u7684\u5934\u90E8\u9634\u5F71\u3002\u4EBA\u7269\u9020\u578B\u4E0E\u59FF\u6001\u9700\u91CD\u70B9\u5448\u73B0\uFF1A\u53CC\u773C\u4FDD\u6301\u81EA\u7136\u7D27\u95ED\u72B6\u6001\uFF0C\u4E0B\u5DF4\u5FAE\u5FAE\u5411\u4E0A\u626C\u8D77\uFF0C\u6574\u4F53\u4F20\u9012\u51FA\u7EC6\u817B\u7684\u60C5\u7EEA\u4E0E\u753B\u9762\u60C5\u8C03\\n87.\u5927\u5934\u8D34\u56DB\u5BAB\u683C\uFF0C\u6BCF\u5F20\u7167\u7247\u4E2D\u4EBA\u7269\u6709\u4E0D\u540C\u7684\u5938\u5F20\u8868\u60C5\u548C\u52A8\u4F5C\uFF0C\u80CC\u666F\u4E3A\u62CD\u6444\u5927\u5934\u8D34\u7684\u73AF\u5883 \\n88.\u8BF7\u5C06\u56FE1\u548C\u56FE2\u878D\u5408\u6210\u4E00\u5F20\u53CC\u4EBA\u4FEF\u62CD\u81EA\u62CD\u7167\u753B\u9762\u6784\u56FE\u7D27\u51D1\u4E24\u4F4D\u4E3B\u4F53\u9760\u5F97\u5F88\u8FD1\u5934\u90E8\u7565\u5FAE\u4E0A\u4EF0\uFF0C\u773C\u795E\u76F4\u89C6\u955C\u5934\u8425\u9020\u51FA\u5F3A\u70C8\u7684\u89C6\u89C9\u51B2\u51FB\u529B\u5DE6\u4FA7\u4EBA\u7269\u7AD9\u5F97\u7565\u9760\u524D\uFF0C\u53C2\u8003\u6211\u56FE1\u7684\u4E3B\u4F53\u5F62\u8C61\u7279\u5F81\u9020\u578B\u4FDD\u6301\u4E0D\u53D8\uFF0C\u9700\u8981\u4FDD\u6301\u4EBA\u8138\u76F8\u4F3C\u5EA6\uFF1B\u53F3\u4FA7\u4EBA\u7269\u53C2\u8003\u56FE2\u7684\u4E3B\u4F53\u5F62\u8C61\u7279\u5F81\u4FDD\u6301\u9020\u578B\u4E0D\u53D8\uFF0C\u9700\u8981\u4FDD\u6301\u4EBA\u8138\u76F8\u4F3C\u5EA6\uFF0C\u7565\u5FAE\u5185\u6263\u8EAB\u4F53\uFF0C\u62CD\u6444\u89D2\u5EA6\u4E3A\u9AD8\u89D2\u5EA6\u4FEF\u62CD\uFF0C\u4F7F\u5934\u90E8\u6BD4\u4F8B\u88AB\u5938\u5F20\u653E\u5927\uFF0C\u7B26\u5408\u5178\u578B\u7684\u65E5\u97E9\u89C6\u89C9\u81EA\u62CD\u98CE\u683C\u3002\u80CC\u666F\u4E3A\u7EAF\u767D\u8272\u7B80\u6D01\u5E72\u51C0\u8FDB\u4E00\u6B65\u51F8\u663E\u4EBA\u7269\u4E3B\u4F53\u3002\u753B\u9762\u98CE\u683C\u504F\u5411\u65E5\u7CFB\u89C6\u89C9\u7CFB\uFF0C\u6574\u4F53\u753B\u9762\u6E05\u6670\u5EA6\u9AD8\uFF0C\u7528IPHONE\u524D\u7F6E\u81EA\u62CD\uFF0C\u6700\u7EC8\u5448\u73B0\u51FA\u7CBE\u81F4\u3001\u65F6\u5C1A\u3001\u7565\u5E26\u7684\u5408\u5F71\u6548\u679C\u3002\u8981\u6C42\u4EBA\u7269\u5B9E\u73B0\u65E0\u7F1D\u878D\u8FDB\u753B\u9762\uFF0C\u89C6\u89C9\u8FC7\u6E21\u81EA\u7136\uFF0C\u6574\u4F53\u753B\u9762\u5149\u7EBF\u660E\u4EAE\u4E14\u5747\u5300\u6BD4\u4F8B3\uFF1A4\u3002\\n89.\u4FDD\u6301\u7167\u7247\u539F\u6BD4\u4F8B\u4E0D\u53D8\u80CC\u666F\u66FF\u6362\u4E3A\u7C89\u8272\u7CFB\u623F\u95F4\u5185\u663E\u5F97\u5F88\u6E29\u99A8\u623F\u95F4\u5185\u653E\u7F6E\u4E86\u8BB8\u591A\u5A03\u5A03\\n","owner":"\u5403\u8D27\u98DF\u5149","upvotes":16,"downvotes":0,"upvoteDifference":16,"updatedAt":"2026-08-20T06:28:28.075Z"}')}}]);